create table public.together_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
alter table public.together_admins enable row level security;revoke all on public.together_admins from public,anon,authenticated;
insert into public.together_admins(user_id) values('77e80d4d-0afb-4ca8-94ec-c03da549dd2b') on conflict do nothing;
alter table public.together_reports add column status text not null default 'open' check(status in('open','reviewed','dismissed'));
alter table public.together_reports add column reviewed_at timestamptz;
alter table public.together_reports add column reviewed_by uuid references auth.users(id) on delete set null;
create function public.together_is_admin() returns boolean language sql security definer set search_path='' stable as $$select auth.uid() is not null and exists(select 1 from public.together_admins a where a.user_id=auth.uid())$$;
create function public.together_admin_reports() returns table(report_id bigint,reporter_name text,reported_name text,reason text,status text,created_at timestamptz) language plpgsql security definer set search_path='' stable as $$begin if not exists(select 1 from public.together_admins a where a.user_id=auth.uid()) then raise exception 'admin required' using errcode='42501';end if;return query select r.id,coalesce(a.display_name,'Użytkownik'),coalesce(b.display_name,'Użytkownik'),r.reason,r.status,r.created_at from public.together_reports r left join public.together_discovery_profiles a on a.user_id=r.reporter_id left join public.together_discovery_profiles b on b.user_id=r.reported_id order by case when r.status='open' then 0 else 1 end,r.created_at desc limit 200;end$$;
create function public.together_admin_review_report(p_report_id bigint,p_status text) returns void language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from public.together_admins a where a.user_id=auth.uid()) then raise exception 'admin required' using errcode='42501';end if;if p_status not in('reviewed','dismissed') then raise exception 'invalid status' using errcode='22023';end if;update public.together_reports set status=p_status,reviewed_at=now(),reviewed_by=auth.uid() where id=p_report_id;if not found then raise exception 'report unavailable' using errcode='P0002';end if;end$$;
revoke all on function public.together_is_admin(),public.together_admin_reports(),public.together_admin_review_report(bigint,text) from public,anon;grant execute on function public.together_is_admin(),public.together_admin_reports(),public.together_admin_review_report(bigint,text) to authenticated;
